// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint160 toRaw, uint256 amount) public {
        address to = address(uint160(bound(toRaw, 1, type(uint160).max)));
        vm.assume(amount > 0);

        address[] memory tos = new address[](1);
        tos[0] = to;
        uint[] memory vals = new uint[](1);
        vals[0] = amount;

        vm.prank(owner);
        bool ok = c.transfer(tos, vals);

        assertTrue(ok, "successful transfer must return true");
    }
}
